quests[29793] = { id = 29793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evil from the Seas", description = "I do not know what this evil is that is infesting the forest, {name}, but I know exactly how to deal with it. So do you, I think.", completion = "You make me proud, {name}. You make all of us proud.", objectives = "Kill 8 Darkened Horrors or Darkened Terrors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29794] = { id = 29794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "None Left Behind", description = "Your friend has been doing everything she can to save my crew. I'm deeply appreciative.\n\nWe're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads.\n\nI still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?", completion = "I have no idea who you people are, but fate surely smiled on us this day. Many more would be dead if not for the help of you and your friends. I am in your debt.", objectives = "Rescue 3 Injured Sailors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29795] = { id = 29795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Stalks", description = "My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons.\n\nI have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.", progress = "The Horde does not back down from a fight.", completion = "These are excellent! We'll have them crafted into weapons in no time.", objectives = "Gather 10 Broken Bamboo Stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29796] = { id = 29796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgent News", description = "I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, {name}? She needs to know what we're doing so she can get everyone to safety.", completion = "Your friend is out fighting to save my crew. Fiercely I might add. I'm afraid your message may have to wait.", objectives = "Speak to Delora Lionheart at the Wreck of the Skyseeker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29797] = { id = 29797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medical Supplies", description = "We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.", progress = "Did you find the boxes I spoke of?", completion = "These will do perfectly. I'll get my medics to work immediately.\n\nThank you.", objectives = "Recover 8 Crates of Medical Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29798] = { id = 29798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Evil", description = "{name}, I was looking for you!\n\nOne of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!", completion = "<Aysa is clearly exhausted from the fight.>\n\nYour skills in battle... are unquestionable... {class}.\n\n\n\nDid you save the escaped prisoners?  ...Where is Ji? Is he okay?", objectives = "Defeat the Vordraka, the Deep Sea Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29799] = { id = 29799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Healing of Shen-zin Su", description = "This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su.\n\nFind any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound.\n\nKeep the healers safe at all costs!", progress = "We need to get the healers to the wound and keep them safe!", completion = "You are a sight to see when under pressure, {name}! We wouldn't have stood a chance without you.\n\nI think it's working. The flow of blood is slowing. I knew it would work!", objectives = "Rescue and defend healers until Shen-zin Su's wound is healed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29800] = { id = 29800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Allies", description = "{name}, I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that.\n\nThere will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.", completion = "It is good to see you again, {name}. You've done all that I've asked of you and more... you have saved Shen-zin Su.\n\nYou make an old master proud.", objectives = "Return to the Temple of Five Dawns. A cart is waiting near the Wreck of the Skyseeker to take you there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Hello, {name}! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right <man/woman> for the job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up to the task?", progress = "Have you completed our task?\n\nThese artifacts are crafted such that they dissolve if their bearer is killed, so only a skilled thief can acquire them.", completion = "You've found one! You're a credit to your race, {name}.\n\nRings like these are capable of decoding even the most complicated of ciphers. Unfortunately, the ring is inert until it is charged...", objectives = "Pickpocket a cryptomancer's decoder ring from Hagara the Stormbinder at the Eye of Eternity within the Dragon Soul raid encounter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29802] = { id = 29802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hidden Message", description = "Corastrasza, currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher!\n\nTake your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking...", progress = "I was hoping Lord Afrasastrasz would find us a competent {class}.\n\nWhat have you got for us, {name}? Do you have a means of decrypting the message?", completion = "What's this about? \"Ravenholdt Manor?\" I thought that was just a motley band of thieves up in the Hillsbrad Foothills.\n\nWhat would they want with a dragon egg? More importantly, how did they find out about it?\n\nWe're going to need some answers, {name}!", objectives = "Charge your Cryptomancer's Decoder Ring and use it to decode the Corastrasza's Singed Cipher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of the Lich King", description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by doing so.", completion = "I bet the pale whelp felt that!\n\nThat's one more step towards yer judgment day, Arthas!", objectives = "Defender Mordun inside Utgarde Keep wants you to slay Prince Keleseth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29804] = { id = 29804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seein' Red", description = "I was just about ta curl up an' die, mon.\n\nNow, dis!\n\nSnuff an' me go way back. Oh, da memories...\n\nNo way I can face Snuff in da afterlife without avengin' his death first, mon!\n\nDese hooligans be led by one named Konk. We gotta sniff him out an' den snuff him out - for Snuff!", completion = "Zin'jun is lost?\n\nThis is a dark day indeed, brother. These vermin will pay!", objectives = "Kill Konk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29805] = { id = 29805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Found Mishka at Plane" }
quests[29806] = { id = 29806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wanderer", sourceObjective = "Defeat the Roaming Brawler in a fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub.\n\nHe has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King.\n\nBring an end to his reign.", progress = "Is it done, {class}? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Azak's eyes as he stares at the husk.>\n\nIt is DONE!\n\nYour name shall be recorded in the extensive history of our people, {race}!", objectives = "Reclaimer A'zak in Azjol-Nerub has tasked you with defeating Anub'arak. You are to return to A'zak with Anub'arak's Broken Husk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise.\n\nThe eggs have been tainted with foul magics. Our only recourse is to dispose of them.", completion = "Do not worry, {race}.\n\nThe eggs they found were but a fraction of our hidden stores within Azjol-Nerub.\n\nOur mighty kingdom shall be reborn.", objectives = "Reclaimer A'zak in Azjol-Nerub wants you to destroy 6 Nerubian Scourge Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29809] = { id = 29809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Efficient Excavations", description = "This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects.\n\nAfter a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here.\n\nA map on the back cover indicates that the author has a bunker in the southwest region of Uldum.\n\nPerhaps an introduction is in order.", objectives = "Bring 'Efficient Excavations' to Belloc Brightblade in Schnottz's Landing.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29810] = { id = 29810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground. In desperation, they dug too deep.\n\nWe inadvertently exposed a tendril of the old god's will, which was made manifest in the creatures known only as the Faceless.\n\nIn the end, we could not fight on two fronts against such powerful enemies. Our misfortune cost us the war against the undead, and ultimately, our home.\n\nEnter Ahn'kahet, {class}, and cleanse our former home of these Faceless atrocities.", objectives = "Kilix the Unraveler in the Pit of Narjun wants you to kill Herald Volazj and the three Forgotten Ones that accompany him in Ahn'Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gatewatcher's Talisman", description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", progress = "Has Krik'thir's spirit been released from the curse of undeath? What of the talisman?", completion = "Just as I suspected.\n\nMost of the empire has remained closed off since Krik'thir's final stand. Perhaps my people have already secured the depths and merely await release? Perhaps the faceless ones fester behind closed doors.\n\nOnly time will tell. The exposed upper reaches of Azjol-Nerub must first be cleansed of Arthas' taint.", objectives = "Reclaimer A'zak in Azjol-Nerub wants you to retrieve the Gatewatcher's Talisman from Krik'thir the Gatewatcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29812] = { id = 29812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Cuddlies", description = "The Fox Grove has become a dangerous place for the local red pandas. \n\nSadly due to my actions helping that crazy Brewmaster Shadowpour, the foxes of the grove have developed an inebriation bite.  The result is the little red pandas keep getting drunk until they can no longer defend themselves.  \n\nPlease!  Can you help me?\n\nIf you round up some of them I have an aroma about this fire that will help sober them up.  That should keep them safe for at least a short while.", objectives = "Lasso 5 Drunk Red Pandas in Fox Grove and bring them to Apprentice Ji Alerage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29813] = { id = 29813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethal Hangovers", description = "I told him not to do it!  But \"no one stands in the way of Brewmaster Shadowpour\".\n\nMy master went and contaminated the local water supply trying to \"add flavor\" to the water. The toxins trickled down here to the Fox Grove where the brew has an irreversible effect on the foxes. \n\nIt warps their minds and sends them into a frenzy.  Now they are a permanent danger to any travelers and local wildlife.\n\nCan you help me cull some of their numbers please?", objectives = "Kill 8 intoxicated foxes in the Fox Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29814] = { id = 29814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need a Chaser", description = "It appears now that my master managed to poison the entire local water supply with his flavor experiments.\n\nI might have a treatment but need some supplies.  In lighter cases my people have found orchids to be a wonderful remedy.\n\nDefeat the orchid chasers in the Orchis Hollow and collect some of the pollinated orchids they carry. We will use them to cleanse the central water source.", objectives = "Defeat Orchid Chasers and obtain 15 of the Pollinated Orchids they spawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29815] = { id = 29815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forensic Science", description = "These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up.\n\nThis one's taken quite a beating, but I've still made some determinations about its anatomy.\n\nWith the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me.\n\nGo and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.", progress = "I hope you were successful. Our survival here may depend on it.", completion = "Oh, yes, {name}. This will do nicely.", objectives = "Collect 8 Viscous Chlorophyll.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29816] = { id = 29816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get a Sample", description = "It is time the Mad Brewer got a taste of his own poison.\n\nTo the east are a number of pandaren who attended a near fatal \"tasting\" session of Shadowpour's.\n\nCan you head into the valley and see if they have any samples left of what they taste tested last night. If you get enough samples I can try to recreate his concoction.\n\nGive the samples to my friend Jian.  He should be able to modify them a bit.\n\nOh, and be careful.  It would appear his beverage had some hateful side effects.", objectives = "Obtain 8 Toxin Samples from smashed pandaren and bring them to Jian in the Valley of the Mad Brewer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29817] = { id = 29817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drunken Tigers", description = "Orchids may be the cure for my people, but they are an intense opiate for the local tigers.  These beasts are often drawn to orchid fields and the intoxicating effects the flowers have on them.\n\nWhen you add the toxins Shadowpour introduced to the water supply it results in very dangerous and rabid animals.  It won't be long before they are threatening the Jade Temple. \n\nCan you thin some of their numbers please?", objectives = "Kill 9 rabid tigers in the Orchis Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29818] = { id = 29818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fix the Flavor", description = "These orchids you gathered might help us fix the larger issue.\n\nIn the valley east of here is the lake Brewmaster Shadowpour contaminated.  Travel there and toss these herbs in the water to draw out the contamination so you can defeat it.  \n\nSpeak to my friend Jian when you are done.  He's a friendly water sprite that has helped the brewmaster and myself make a number of recipes.", objectives = "Use Cleansing Orchids near the lake water in the Valley of the Mad Brewer and defeat the resulting contaminations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29819] = { id = 29819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Master", description = "I figured it out!  With the toxins you provided I not only recreated Shadowpour's recipe but also fixed the problem he was having that was causing illness.\n\nDo you know what this means?  All that flavor and none of the lethal side effects!\n\nNow to deal with the Brewmaster.  I've loaded up Chalky with samples. Can you take these to challenge Shadowpour to a tasters' duel?\n\nYou'll be subjected to his brews but I will help you cheat by bringing my sobering fire.", objectives = "Travel to the Tasters' Arena and challenge Brewmaster Shadowpour to a tasters' duel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Nexus", description = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", sourceObjective = "Archmage Berinand has asked you to speak with Warmage Kaitlyn in the Nexus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29821] = { id = 29821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missed Me By... That Much!", description = "Listen, <pal/toots>.\n\nI sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is.\n\nOne of 'em buzzed right through the camp here and crashed out by them waterfalls.\n\nHow 'bout you see what you can do about bringin' the contents of that crate back here, hmm?\n\nWe're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be.\n\nHah! I just kill me...", completion = "This crate should be full of supplies...", objectives = "Find the missing supply crate at Serenity Falls.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29822] = { id = 29822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land", description = "Curse these furry pests! Kill one, and two more rise in its place...\n\nNothing has changed, {name}. Orders are orders, no matter how few of us stand and regardless of the odds.\n\nI have plans to make and problems to solve.\n\nI want you to get out there and learn the lay of the land. Don't return until you have something useful to report.\n\nAnd silence that yammering fool while you're out there!\n\nDismissed!", completion = "Welcome, traveler.\n\nPlease, make yourself comfortable.", objectives = "Visit the Shrine of the Sun, the Shrine of the Moon, and Kill Dook Ookem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29823] = { id = 29823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: The Friend of My Enemy", description = "We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu!\n\nWell, we found 'em all right...", progress = "Riko wishes you were a bit more patient, {name}.", completion = "Yeah, I ran away. So blikkin' what? If it weren't for me, Kiryn would be dead. Oh, wait... she's already dead... already...\n\nGo away! Riko's head hurts.", objectives = "Listen to Riko's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29824] = { id = 29824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report: Like Jinyu in a Barrel", description = "With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do:\n\nMarch into our enemy's territory and deliver some vengeance.\n\nWant to know how it went?", progress = "I'm not quite done yet, {name}.", completion = "The most important thing we learned was that... not only have the Alliance befriended the jinyu, but they're giving them weapons, and teaching them how to use them.\n\nThe Alliance now control a force that outnumbers us thirty-to-one. And we - the HORDE - have befriended monkeys.", objectives = "Listen to Shokia's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupil No More", description = "I once called Elder Nadox my teacher.\n\nThat changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned.\n\nFind him within the depths and make him pay for his crimes, {race}.", progress = "Is the mighty Nadox dead for good?", completion = "With Nadox gone, I hope to take his place as a leader of my people.\n\nThe Empire of Azjol-Nerub is destined for greatness, {race}...", objectives = "Seer Ixit in Ahn'Kahet has tasked you with the assassination of Elder Nadox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Ahn'Kahet", description = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths.\n\nDeactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", progress = "Much work remains to be done in Ahn'Kahet, even long after the Scourge are defeated.", completion = "Excellent.\n\n<You heard a series of clicking sounds.>\n\nNow to vanquish our other foe.", objectives = "Seer Ixit in Ahn'Kahet wants you to kill 3 Eyes of Taldaram, a Bonegrinder, and Prince Taldaram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29827] = { id = 29827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acid Rain", description = "Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault!\n\nWe're going to have to take some drastic measures if we hope to see tomorrow.\n\nHere, take my poisoned throwing stars and figure out a way to thin out their numbers.", progress = "Well, {name}? Do we live to see another day?", completion = "Excellent! What a creative solution!\n\nThat should hold them off for a while.", objectives = "Using the Recovered Gyrocopter, kill 25 Hozen Gutrippers and 25 Hozen Nibstabbers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Scourge Dred", description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", progress = "Does the great beast exist?", completion = "<Kurzel's eyes open wide.>\n\nWow! That's enormous!", objectives = "Kurzel inside Drak'Tharon Keep wants you to slay King Dred and bring her his tooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, {class}?", objectives = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Lieutenant Sinclari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment", description = "My forces are in absolute shambles, and Malygos' assailants just keep coming.\n\nI fear that the worst has yet to come.\n\nYou must engage them until their leader, Cyanigosa, comes. Only her death will stop the invasion and save Dalaran.\n\nSpeak to me again when you are ready.", progress = "Is it over? Were you able to withstand the assault?", completion = "Thank you, hero!\n\nDalaran is safe for another day because of your bravery.", objectives = "Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.", completion = "Lissen up, mon. Dere be dangerous work ta be done!", objectives = "Har'koa wants you to speak with Tol'mar in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nMy job be to observe only. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", progress = "Has Akali's death been avenged, {race}?", completion = "Ya done it?! Dey be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to da frozen wastes.", objectives = "Tol'mar wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "Da mighty Akali has been slain, {race}.\n\nMy role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", completion = "Ya really did it?\n\nYou surpassed my expectations, mon. Take dis gift for bringin' justice to da frozen wastes.", objectives = "Chronicler Bah'Kini wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from inside Gundrak. Perhaps you could find the time to check in on her for me?", completion = "To'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!\n\nDis place be full of troll history. We can't let Gal'darah and his crazed followers keep it hidden forever!", objectives = "To'kini wants you to speak to Bah'kini in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29837] = { id = 29837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Scroll", description = "The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of.\n\nYou suspect that, like everything else these Hozu possess, this is stolen merchandise.\n\nPerhaps the original owner of the scroll is still nearby...", objectives = "Bring the Illegible Scroll to Lorewalker Cho.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nIf what I learned be true, den dey have a special golem - one like nuthin' created before!\n\nBring me back a piece from dat golem ta study.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles.", objectives = "Chronicler Bah'Kini wants you to recover a piece of the Drakkari Colossus in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our bruddas and sistahs.", progress = "You find da golem? I'm sure it's in there somewhere.", completion = "Amazin'! Dis be like nothing I've ever seer before.\n\nGood work, mon.", objectives = "Tol'mar wants you to recover a piece of the Drakkari Colossus in Gundrak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be bringin' dem back to der former glory.", progress = "You find da Drakkari history tablets, mon?", completion = "You be havin' my thanks, mon.\n\nThese will be very useful to us, I'm sure of it.", objectives = "Chronicler Bah'Kini in Gundrak wants you to collect 6 Drakkari History Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29841] = { id = 29841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land[TEMP]", description = "Grah!!\n\nFor every one of these muck-flingers we kill, another two spring from the woods to take its place. I wouldn't share this with the others, but it's clear that we won't last long here, {name}.\n\nI must stay and defend what remains of our belongings. You scout out the region and seek a solution to our primate problem.\n\nGo now. Our hope goes with you...", sourceObjective = "Explore the region.", sourceObjectiveStatus = "unverified-source-field" }
quests[29842] = { id = 29842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Answers", description = "<Cho endures your stream of questions before speaking.>\n\nSo much to ponder, traveler...\n\nYou first must learn how to ask before your mind can discern the truth.\n\nI have completed my meditations for today, but my candles remain at the Cairn of Blood.\n\nGo there. Clear your mind. We will speak again when you are prepared to hear my words.", objectives = "Use the candles to meditate at the Cairn of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29843] = { id = 29843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aunty Lin Windfur", description = "We will start heading back to town once everyone gets organized.  No way is anyone going to mess with me now!  I'll boot them in the head! I'm sure I won't be in trouble after this.\n\nThank you so much for your help. Can you tell Aunty Lin back in Panda Town that we are okay and on our way back?  She has tons of old cool stuff she might give you as a reward.", sourceObjective = "Speak with Lin Windfur in Panda Town.We will start heading back to town once everyone gets organized. No way is anyone going to mess with me now!  I'll boot them in the head! I'm sure I won't be in trouble after this.\n\nThank you so much for your help. Can you tell Aunty Lin back in Panda Town that we are okay and on our way back?  She has tons of old cool stuff she might give you as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Da land of da ice trolls is a shadow of its former glory.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be givin' dis land back to a new line of frost trolls.", progress = "You find da Drakkari history tablets, mon?", completion = "We trolls been subject to da splittin' of empires for longer than some races been existin'.\n\nWe always regrow from da ruins.", objectives = "Tol'mar in Gundrak wants you to collect 6 Drakkari History Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29847] = { id = 29847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Catch a Thief", description = "Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen!\n\n<Mostrasz places an enchantment on you.>\n\nThere - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...", completion = "So, you will join with me?\n\nGood. Very good.", objectives = "Infiltrate Ravenholdt Manor and locate the missing black dragon egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forlorn Watcher", description = "I would gladly give my life for the Makers or their creations.\n\nHowever, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay her to rest and bring me one of her tears.", progress = "I wish there were another way, but it seems death is the maiden's only salvation now.", completion = "<Kaldir stares into the crystal in silence for a moment.>\n\nNo being has ever felt such sincere sorrow as the Maiden of Grief has.\n\nLet us remember her spirit as we continue our efforts against Loken.", objectives = "Kaldir Ironbane in the Halls of Stone has asked you to put the Maiden of Grief to rest and to obtain a Crystal Tear of Grief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupt Constructs", description = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, Krystallus, and the dark rune giants already walking the halls before it is too late!", completion = "Well done, {race}.\n\nEvery weapon we can take away from Loken is a great boon to our own war effort.", objectives = "Kaldir Ironbane in the Halls of Stone has asked you to kill 3 Dark Rune Giants and Krystallus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the Tournament", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, fight with valor and honor. Every fighter here has gathered for the common good.\n\nTogether, we will stop Arthas!", objectives = "Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29853] = { id = 29853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the King", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, you are to represent the Alliance in this grand arena.\n\nProve yourself against Azeroth's finest. Go forward with honor.", objectives = "King Varian Wrynn has tasked you with the completion of the Trial of the Champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29856] = { id = 29856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cairn of Bone", description = "Your mind felt clear.\n\nYou thought you were focused.\n\nMaybe it was the droning of the nearby insects that put you to sleep. That must've been it!\n\nOut of the corner of your eye, you see another of the stone formations just north of here.\n\nPerhaps it's quieter at that one...", objectives = "Use the Meditation Candle at the Cairn of Bone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29858] = { id = 29858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom of the Ages", description = "You must learn to approach your life's trials with humility and an open mind, stranger.\n\nWisdom cannot fit through the narrow slits of the skeptic's eye.\n\nMeet me at the Cairn of Stone and I shall teach you the ancient art of meditation.\n\nOnce you are at peace, you may find that the answers you seek are not as distant as you might think them to be.", objectives = "Speak to Lorewalker Cho at the Cairn of Stone to practice meditation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little {race}. In time, I am certain my people will grow to forgive Thorim.", objectives = "Stormherald Eljrrin in the Halls of Lightning wants you to defeat Volkhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nThe honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my unending gratitude.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little {race}.\n\nPlease accept this gift in return for your loyal friendship.", objectives = "Stormherald Eljrinn in the Halls of Lightning wants you to defeat Loken. You are then to return to Stormherald Eljrinn with Loken's Tongue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves.\n\nNow is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", progress = "Have you vanquished their forces?", completion = "Though few outside of us shall ever know it, you have certainly saved the world on this day.", objectives = "Stormherald Eljrrin in the Halls of Lightning wants you to kill 3 Stormforged Menders, 3 Stormforged Tacticians, and General Bjarngrim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormherald Eljrrin", description = "I have sent an emissary to the Halls of Lightning to take the battle to Loken.\n\nHe undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.", completion = "Our time to act is short. Loken prepares for war.", objectives = "King Jokkum wants you to enter the Halls of Lightning and speak with Stormherald Eljrrin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working at the Source", description = "We are hard at work ensuring that we minimize our losses to the Scourge war machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", progress = "I have faith in you, {name}.", completion = "Every soldier we deny to the Scourge is more than one life saved.\n\nThank you.", objectives = "Argent Confessor Paletress wants you to slay Svala Sorrowgrave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29865] = { id = 29865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silkwood Road", description = "West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path.\n\nI would face these villains myself but someone has to defend the noodle shop from... um... dangers and such.\n\nGo, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism.\n\nI'll also pay you.", progress = "The silkwood stalkers are not in balance with nature. Predators are one thing but these creatures kill for pleasure. Harmony must be restored.", completion = "Such a noble hero. You remind me of a younger, less good looking version of myself.", objectives = "Defeat 8 Silkwood Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29866] = { id = 29866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threads that Stick", description = "Ah, welcome traveler. I have need of your services!\n\nSyra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur.\n\nI really want to impress her though.\n\nIf you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.", progress = "Did you find the Silkwood?", completion = "Oh thank you so much! This is perfect!\n\nI hope it didn't stick to you like it stuck to me.\n\nI'm going to go find Syra and give this to her right away!", objectives = "Gather 7 Pristine Silk Strands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29869] = { id = 29869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Hand Clapping", description = "You have much yet to learn, but your feet are now on the path to enlightenment.\n\nTake what I have taught you here and apply it at the lake to the west.\n\nWith patience and practice, harmony and enlightenment can be attained. Then, wisdom will flow freely into your mind.\n\nAlso, you will be far enough away that your snoring will not interfere with my own studies.\n\nFarewell, stranger.", objectives = "Meditate at the Cairn of Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29871] = { id = 29871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clever Ashyo", description = "I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them.\n\nQuite the opposite, actually.\n\nAt least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission.\n\nIf you want to help him look for the Hidden Master, you can find him along the Valley's northern border.", completion = "Where have I seen you before?", objectives = "Find Clever Ashyo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29872] = { id = 29872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lin Tenderpaw", description = "Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us.\n\nPerhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.", completion = "Oh, it's you!\n\nNo, I haven't found the Hidden Master yet. I probably wasted my time coming out here.\n\n<Sigh...>", objectives = "Find Lin Tenderpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29873] = { id = 29873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken-Ken", description = "So... Ken-Ken. The hozen.\n\nPersonally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind.\n\nHe said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds, down the path to the south. See what he's found.", completion = "This place... it... it so SAD!\n\nKen-Ken never seen a place so sad.", objectives = "Find Ken-Ken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29874] = { id = 29874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?", objectives = "Find Kang Bramblestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29875] = { id = 29875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kang Bramblestaff", description = "Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds.\n\nI wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave {race} was looking out for him.", completion = "I'm pretty sure this settlement wasn't here a few weeks ago. Where did these people come from?", objectives = "Find Kang Bramblestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29877] = { id = 29877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poor Grasp of the Basics", description = "Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb.\n\nYou no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground.\n\nThey was WATERING them. They was trying to GROW WHEELBARROWS.\n\nPlease, while you out there, unbury our stuff.", progress = "Man, those virmen is dumb.", completion = "Thanks, friend. Now maybe a hozen can get some ookin' work done around here.", objectives = "Unearth 7 pieces of farm equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29878] = { id = 29878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building a Better Hozen Trap", description = "One thing is now painfully clear. The Hozen love their 'slickies'.\n\nWhile deep in your meditative trance, scattered images and impressions came to your mind. Now fully awake, you struggle to make sense of the experience.\n\nThe beginnings of an absurd plan begin to take shape in your head. It might just be crazy enough to work...", objectives = "Collect 8 Slickies and 8 Intact Pottery Jars from Lake Kittitata.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29879] = { id = 29879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swallowed Whole", description = "Now, back to your dilemma.\n\nI believe you can help your people build relations with our hozen, as my people have.\n\nThe trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them.\n\nAround this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them.\n\nIf you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.", progress = "Wikket got slickies... for me!?", completion = "Wikket save hozen? And bring slickies?\n\nHmm, maybe wikket not so bad.\n\nTooki Tooki never liked Dook Ookem anyway...", objectives = "Free 5 hozen from the Engorged Crocolisks, and gather 5 Speckled Trout from Lake Kittitata.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29880] = { id = 29880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch and Release!", description = "As you place one fish in each jar, your optimism grows.\n\nThis just might work! Ideally, rescuing the Hozen from your makeshift trap will soften their stance towards you.\n\nTime to set some bait.", objectives = "Use Hozen Traps in Camp Nooka-Nooka, then break them to free 5 trapped Hozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29881] = { id = 29881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Color", description = "As you have seen, this grove is abundant with beautiful pink petals.  As each petal ages, the tone deepens and fades.\n\nIf you would be so kind, I am in need of a few petals that have freshly fallen.  Only the ones that have just fallen will have precisely the right color I am after.\n\nFrom it I can forge an ink that will be breathtaking.  Can you help me?", progress = "There is only a small window of time after each petal falls that it may be used to achieve the perfect hue.", completion = "Ah! You have a wonderful eye for color my friend.  These will make a superb pigment.", objectives = "Gather 8 Freshly Fallen Petals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29882] = { id = 29882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quill of Stingers", description = "To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair.\n\nHave you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line.\n\nCould you gather some for me please?", progress = "Have you been able to acquire some stingers? I would normally ask a monk for help with this but they all seem to be elsewhere at the moment.", completion = "My thanks traveler. These will make a fine set of quills. Here is something for your trouble.", objectives = "Gather 6 Wasp Stingers from Orchard Wasps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29883] = { id = 29883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pearlfin Situation", description = "I've been thinking.\n\nWe are cut off from support and a long way from home.\n\nAlthough these Pearlfin jinyu mistrust our presence, they do not appear to be hostile.\n\nIf we could convince them that we are their friends, an alliance between our races could prove extremely valuable.\n\n{name}, you must go speak to the jinyu around the village.\n\nConvince their leaders that we are not to be feared, and that we only wish for peace.", progress = "If we can win over the jinyu, they may allow us to stay.", completion = "It sounds like you made quite the good impression.\n\nWell done, {name}!", objectives = "Speak to Elder Lusshan, Pearlkeeper Fujin, Instructor Sharpfin, and Ot-Temmdo at Pearlfin Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29884] = { id = 29884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Spies Leave", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.", objectives = "See the scouts off, then speak to Big Lu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29885] = { id = 29885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Road Rations", description = "We do not have time to wait around for the Admiral to recover.\n\nSully and I are planning to search for Anduin to the north, but we'll need supplies for our journey.\n\nThe lake here is teeming with wildlife, which we have received permission to hunt.\n\nGo and gather some supplies while Sully and I finalize our preparations.", progress = "Time is short. Each hour we delay, the White Pawn may move further away.\n\nWhere are the supplies I asked for?", completion = "This should be plenty, {name}. Thanks.", objectives = "Collect 6 Tortoise Flanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29886] = { id = 29886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen Healing", description = "Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure.\n\nLuckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries.\n\nThe flowers growing on the surface of Glass Lake are needed to make the antidote.\n\n{name}, go quickly and bring back some blooms. Your Admiral's life depends on it.", objectives = "Collect 6 Zen Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29887] = { id = 29887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elder's Instruments", description = "Oh dear, oh dear... The Elder mustn't find out!\n\nI must have left the Elder's ceremonial instruments behind during the escape.\n\nBut... Moonwater Retreat is crawling with hozen by now!\n\nWhat sort of Pearlkeeper am I, to have lost them so carelessly?\n\n<The old jinyu buries his face into his hands.>\n\nStranger, could you find it in your heart to help me?", progress = "The Elder is a Waterspeaker. He speaks to the waters, and they answer.", completion = "You found them? Oh thank the spirits of water!\n\nYou have saved my tailfin, {name}.", objectives = "Collect the Waterspeaker's Staff, Ceremonial Robe, Jade Crown, and Rosewood Beads from Slingtail Stickypaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29888] = { id = 29888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Lorewalker", description = "I see that you and your people are desperate to find your Prince Anduin.\n\nI know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him!\n\nThe Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.", completion = "You look around the empty house.\n\nIt appears you are in the right place, but there is no sign of its inhabitant.", objectives = "Search for Lorewalker Cho at the Dreamer's Pavilion in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29889] = { id = 29889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Brew", description = "A delicious smell wafts out from the bottle on the table.\n\nA little taste couldn't hurt, right?", completion = "I heard your people had washed up on our shores, but I did not expect to find one washed up on my very doorstep! What brings you here, stranger?\n\n<You explain about your search for Prince Anduin, and describe the boy to the pandaren.>\n\nVery interesting! And so the Pearlfin sent you to me, did they?", objectives = "Taste the mouthwatering brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29890] = { id = 29890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Your Center", description = "The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus.\n\nFollow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much.\n\nYour troubled mind will present you with many distractions, but just remember to stay centered!", completion = "How did you find me?\n\n<Anduin listens to you describe the vision from the Dream Brew.>\n\nRemarkable! That's exactly what happened several days ago. We've been laying low since then.", objectives = "Meditate with Lorewalker Cho at the pagoda at the Dreamer's Pavilion in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29891] = { id = 29891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potency", description = "To make the Dream Brew, we will need several ingredients.\n\nFirst, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror.\n\nIt is said that this creature only appears where the fog is deepest.\n\nNorth and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.", progress = "The mists seem to have a mind of their own, do they not?", completion = "This is an amazing specimen! I am quite shocked that you have succeeded, actually.", objectives = "Kill Mist Creepers until a Mist Horror appears, then collect a Mist Horror Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29892] = { id = 29892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body", description = "A brew's body is an important and often overlooked factor.\n\nTo create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east.\n\nTake care. The creatures are quite vicious.", progress = "Watch your step in the swamp, my new friend.", completion = "Do you have crocolisks where you are from?", objectives = "Collect 5 Pristine Crocolisk Eyes from Bog Crocolisks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29893] = { id = 29893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hue", description = "The most distinguishing feature of the Dream Brew is its iridescent, dream-like color.\n\nTo the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew.\n\nTake this knife and use it to collect 8 wings.", progress = "Have you collected all the ingredients? It is almost time to make the Dream Brew.", completion = "Beautiful color, rare transparency, shimmer but not sparkle...these will do quite well.\n\nI am beginning to see great potential in you, strange one.", objectives = "Collect 8 Amberfly Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29894] = { id = 29894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Water", description = "Our war against the hozen rages without end, and the future of our tribe is uncertain.\n\nThis is why our waterspeaker has decided to seek wisdom from the waters.\n\nElder Lusshan is waiting. Please deliver the instruments so that they may begin.", progress = "<The Elder's eyes are glazed over. His vision is cast inward, toward the wisdom he has gained.>", completion = "I saw the vision, {name}. What do you think it means?\n\nI think it is clear that you play some part in it.", objectives = "Speak to Elder Lusshan and witness the waterspeaking ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29895] = { id = 29895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of the White Pawn", description = "Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest.\n\nYou should show it to your Alliance commander.", completion = "This is Anduin's cloak, {name}!\n\nThis must mean he passed through this forest.\n\nWe must heighten our efforts to find him.", objectives = "Show the cloak to Admiral Taylor at Pearlfin Village in the Jade Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29896] = { id = 29896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steaking a Claim", description = "Since we're already out here, no sense in going back empty-handed, right?\n\nNow, did you know that the porcupines around these parts have just about the rarest, juiciest steak a person has ever tasted?\n\nThey're difficult to hunt because of their sharp spikes, but you look like you can handle your own.\n\nGo on and round me up a couple of steaks to take back to camp.\n\nWe may be roughing it out in this wilderness, but we can still eat like kings!", objectives = "Collect 5 Porcupine Steaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29897] = { id = 29897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Such Thing As A Free Lunch", description = "The fighting's over, but we're not out of trouble yet. Not by a long shot.\n\nOur camp is falling dangerously low on supplies, but our provisioner didn't make it back from the battle.\n\nSome of the troops saw her being dragged into the forest to the north.\n\nPlease, would you find her?", sourceObjective = "Find Sandra Emerella at the Veridian Grove in the Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[29898] = { id = 29898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Waters", description = "I appreciate you coming all this way to save me, but Ren is gravely injured.\n\nThe old pandaren had no reason to help me, yet still he risked his life to save my own.\n\nBefore the fever set in, he mentioned that there are healing waters in the cave just down the hill.\n\nIt is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?", progress = "Perhaps I could bring some of these healing waters back to Stormwind with me.", completion = "The healing waters should abate Ren's fever for a short while, but alas, I fear it is no permanent cure.\n\nThank you, {class}. We have granted him a little more time, at least.", objectives = "Collect healing waters from the four Sacred Bowls in the Den of Sorrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29899] = { id = 29899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest in Peace", description = "The spirits... the cavedwellers... they howl in agony... \n\nTrapped... in this world... cannot move... to the next.\n\nI... will go mad... listening... to their cries... \n\nPlease...go...put them to rest.", completion = "Thank you... friend. I am... happy... knowing... the spirits... are at peace.", objectives = "Kill 6 Tortured Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29900] = { id = 29900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Legend", description = "My father has dedicated his life to studying the Vale of Eternal Blossoms.\n\nThe Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it!\n\nMy father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale, but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit.\n\nIf you are heading that way anyway, would you mind bringing it back to him?", progress = "Did you... find the scroll?", completion = "Oh... it is the poem! Did you... read it? What did you learn about the Vale?", objectives = "Retrieve the Song of the Vale from the Den of Sorrow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29901] = { id = 29901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduin's Decision", description = "You have done all you can for the Prince's friends.\n\nYou completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody.\n\nIt is time to return home.", completion = "He did WHAT?!?!?\n\nHe's lucky that I haven't found him yet, because when I do, I just might kill him myself!\n\nWhatever he thinks he's doing... chasing after this Vale... it is not behavior fit for a prince!\n\nIf we didn't have more pressing matters at hand, I would send our entire fleet chasing after his heels!", objectives = "Tell Anduin that it is time to return home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29902] = { id = 29902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting the Flames", description = "Those monkeys seem to be more savage than intelligent, but they're smart enough to know that fire is a powerful weapon.\n\nI don't need to explain that if those fires are left unchecked, they'll destroy everything we've built here.\n\nAll my men have their hands full, so you'll have to do it. Take this bucket of water and put out those flames!", objectives = "Put out 6 fires in Wayward Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29903] = { id = 29903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Match", description = "Elder Lusshan and I agree that the best path forward will be to work together.\n\nWe will share with the Pearlfin our superior military knowledge and weaponry.\n\nIn return, they will be a powerful ally should we again encounter the Horde.\n\nTake this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.", progress = "The jinyu are skilled in different ways. It is up to us to find their strengths.", completion = "Good. Let those Horde mongrels show their faces now!", objectives = "Speak to Pearlfin Aqualytes and arm them with the proper equipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29904] = { id = 29904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger Fish to Fry", description = "I've prepared a team of bright young Pearlfin trainees who need field experience.\n\nTake them northeast, into the Bamboo Wilds, and kill any wildlife that you find.\n\nDon't bring them back until they're fit for battle.", progress = "How are those trainees looking?", completion = "Your trainees returned recently. I could hardly believe my eyes! They did not look like the same jinyu that you left with.\n\nExcellent work, {class}. Couldn't have done better myself.", objectives = "Train the Pearlfin Adepts by killing 24 wildlife in the Bamboo Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29905] = { id = 29905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Burn", description = "Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north.\n\nOur forces are gathered for battle on the ridge to the northwest. They are just waiting for you.\n\nNow is the time to show them what we are made of. Now is the time to destroy them indefinitely.", completion = "The waters were right about you, {name}. Because of your efforts, this village has a future. We will not forget the lessons you've taught us, {class}.", objectives = "Kill 15 Grookin Reinforcements or Slingtail Recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29906] = { id = 29906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carp Diem", description = "Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut, is the shrewd mastermind behind their attacks.\n\nHe is organizing their movements at the great pit at the hozen camp to the northwest.\n\nStrike now and show him no mercy, {name}, for he will do the same.", completion = "Without their leader, these hozen should once again settle into disarray.\n\nToday we rejoice in our victory! {name}, you came to us a stranger, but you depart as a friend.\n\nFrom henceforth, you are the highest of the high - a valued friend and defender of the Pearlfin tribe.", objectives = "Kill Chief Gukgut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29907] = { id = 29907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen and Li Li", description = "My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going.\n\nThat farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li?\n\n{race}? Would you like to share the road with us?", progress = "Yes?", completion = "Welcome, welcome, visitors! You've come to sample some of my son's turnips? Perhaps purchase a few pigs?\n\nPlease, make yourselves at home. I have plenty of room.", objectives = "Follow Chen Stormstout to Pang's Stead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29908] = { id = 29908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Seemingly Endless Nuisance", description = "I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it.\n\nI'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?", progress = "Have you pushed the virmen out yet, {class}? We need to bring in our crops soon, or they'll be lost for sure.", completion = "<Pang surveys the area around his farm.>\n\nWell, they're not ALL gone yet, but there's less of them. And they aren't holding their ears quite as high anymore.\n\nI'd guess that they're scared of you, {name}.", objectives = "Slay 8 Snagtooth Spotters, Tool-Grabbers, or Troublemakers. Then slay 18 Snagtooth Pesterlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29909] = { id = 29909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Low Turnip Turnout", description = "Your help here is appreciated, {name}. I'd like to give you another job, if you're interested.\n\nMy son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day.\n\nWould you go down there and see what's going on?", completion = "Wha-? Who the...? My father sent you?\n\nPshh... he can be so nosy sometimes. I have everything under control here.", objectives = "Find Ang Thunderfoot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29910] = { id = 29910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Rodents", description = "I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots!\n\nI don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes!\n\nFill in their holes with dirt, so they can't come out in our farm anymore.", progress = "The marmots won't be happy when you try to fill in their holes.", completion = "Thank you, sir! Now I can get back to my chores.", objectives = "Move 6 Plump Marmots off of Thunderfoot Farm, and fill in 6 Marmot Holes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29911] = { id = 29911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practically Perfect Produce", description = "Here, {name}. My father will be wanting this.\n\nThank you, again, for helping with the virmen.", progress = "Do I smell turnips?", completion = "Ho ho! Now that's what I like to see!", objectives = "Bring the Crate of Fresh Crops to Pang Thunderfoot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29912] = { id = 29912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fabulous Miss Fanny", description = "Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs.\n\nUnfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out.\n\nBring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.", progress = "Not now, neighbor. I need to scrounge up some food for these pigs.", completion = "I understand you're the one who sent the food down from uncle's farm. Thank you.\n\nMy pigs are picky eaters, but those turnips and watermelons are some of their favorites.", objectives = "Bring Ang's Giant Pink Turnip, Ang's Summer Watermelon, and Pang's Extra-Spicy Tofu to Miss Fanny, and ask her to deliver them. The food must land on Thunderfoot Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29913] = { id = 29913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Meat They'll Eat", description = "I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat.\n\nThey do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west.\n\nMy skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?", progress = "It hurts my ears to hear their hungry squeals.\n\nOnce you've been a pig rancher for a while, you can distinguish hungry squeals from regular squeals.", completion = "<Liang sorts through the meat.>\n\nYou're not just a {class}, but you're a butcher, too? You've got an eye for quality pig food, neighbor.", objectives = "Obtain 4 Mushan Shoulder Steaks and 80 Turtle Meat Scraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29914] = { id = 29914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Sty", description = "I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped.\n\nCare to look for them? I'd start by looking down the hill, to the west.", progress = "Have you found them? There should be three missing, I think.", completion = "There they are! Back into the sty with you three, now!\n\n<Liang looks up at you.>\n\nThank you, neighbor. I'm truly grateful for your assistance.", objectives = "Find Jian, Ling, and Smelly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29915] = { id = 29915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Neighbor's Duty", description = "I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock.\n\nYou should check up on him, neighbor. And bring this poor little thing with you.", progress = "Oh... you have one of my... my lambs?", completion = "You really shouldn't have brought the lamb back to me. He... he was safer in that pigsty than he is over here.", objectives = "Bring the Wayward Lamb to Francis the Shepherd Boy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29916] = { id = 29916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piercing Talons and Slavering Jaws", description = "First the hawks came. You've probably seen some of them circling up above.\n\nThe wolves came shortly after. I think they smelled my weakness.\n\nI'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts.\n\nCan... can you help, <sir/ma'am>?", progress = "I wish I were brave enough to fight them, but...", completion = "They... they're not stopping, but at least we fought back. Right?", objectives = "Kill 5 Thieving Plainshawks and 6 Thieving Wolves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29917] = { id = 29917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupello", description = "I've been thinking... the wolves might stop attacking if we kill their pack leader.\n\nWe call him Lupello, and he patrols the opposite riverbank.\n\n<Francis' concentration is broken by another attack. Perhaps you should go deal with Lupello yourself.>", progress = "What will Master Shang say when he finds out?", completion = "I know I should be the one fighting them off. Maybe I'm not cut out for shepherding after all.", objectives = "Slay Lupello.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29918] = { id = 29918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Bravery", description = "<Master Shang speaks to his shepherd boy.>\n\nFrancis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears!\n\n<He looks over to you.>\n\nYou, stranger. You helped the rest of my family. Francis is like a second son to me.\n\nShow my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us.\n\n<Shang points to the sky, looks at Francis, and leaves.>", progress = "You lack fear. I can sense it in your heart.", completion = "Francis has taken longer than I expected to become an effective shepherd. We all go through these phases... my son Liang was weak once, too. As was I.\n\nBut he will learn. It is the Thunderfoot way.", objectives = "Use the Rancher's Lariat to lasso and defeat a Great White Plainshawk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29919] = { id = 29919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Minds Drink Alike", description = "Hello again, {name}. What is this, the fourth time we've run into one another already?\n\nSay... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?", completion = "If yer lookin' fer beer, you came to the right place, neighbor.\n\nJust, ah... excuse the mess. Had me a bit of a problem with virmen the last few days.", objectives = "Escort Chen Stormstout and Li Li to the brewery in the southwest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29920] = { id = 29920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Permission", description = "My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight.\n\nThing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat.\n\nLo is a good man, but not a fighter.\n\nWould you be our champion?", progress = "Each of the pandriarchs earned their reputation in life and retained them afterward.  I can't even imagine how you will defeat them.", completion = "They... they agreed?! Fantastic! Thank you so much! With their blessing we can be the happiest pandaren in all the land!\n\nPlease, take this. We meant it to be a tribute for the pandriarchs but they didn't seem interested.", objectives = "Challenge and defeat Pandriarch Goldendraft, Pandriarch Windfur, and Pandriarch Bramblestaff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29922] = { id = 29922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Wisdom", description = "Lorewalker Cho came by and asked for you while you were gone.\n\nHe needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say.\n\nSpeak to Kitemaster Ut-Nam. He would be happy to send you there.", progress = "Ah! You made it. Fantastic!", completion = "Your deeds have sparked a long forgotten memory I have of an ancient prophecy. This deserves investigation.\n\nIn order to investigate, I need jade though. I have instructed Toya to gather as much as he can find and give it to you when he is done. Bring it to me and we will see about deciphering the ancient \"Emperor's Omen.\"\n\nWhile he gathers the jade, feel free to explore. You may find the people of this town are in need of a person of your caliber.", objectives = "Speak to Kitemaster Ut-Nam and get a ride to Dawn's Blossom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29923] = { id = 29923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dream Brew", description = "The Dream Brew is ready.\n\nDrink it at the Seer's Stone, just to the right of the red pagoda.\n\nSeek, and find.", objectives = "Drink the Dream Brew at the Seer's Stone and find the White Pawn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29924] = { id = 29924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Kher Shan", description = "Kher Shan is one big dooker.\n\nGrooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember.\n\nWikket wanna help hozen? Go grook Kher Shan!\n\nThe dooker's over there.\n\n<Nibi Nibi points to the east.>", objectives = "Kill Kher Shan in Tigers' Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29925] = { id = 29925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All We Can Spare", description = "Alright, I called in every favor I could. Here's what we got.\n\nCho must be on to something big!\n\nLemme know when you're ready to go see him - I got a ride all prepared for ya.", progress = "Ah, hello again, {name}! You received my message, then?", completion = "I knew Toya would come through for me!\n\nHe can get anything, you know.", objectives = "Deliver the Scavenged Jade to Lorewalker Cho at Emperor's Omen. Speak with Toya in Dawn's Blossom for a ride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29926] = { id = 29926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calamity Jade", description = "You ever seen a shale spider, {class}? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\"\n\nA few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys.\n\nYou get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.", completion = "Well I'll be... you actually did it!\n\nYou lookin' for a more permanent job, buddy? I could use a bruiser like you around full-time!", objectives = "Slay 12 Greenstone Nibblers and 6 Greenstone Gorgers at the Greenstone Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29927] = { id = 29927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mann's Man", description = "<For once, the foreman lowers her voice.>\n\nLook, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\"\n\n<Mann sneers.>\n\nWhat about my moral support?! What am I gonna do if that idiot dies?!\n\nPlease... keep an eye out for him. Tell him to come home.\n\n<Her eyes soften before she turns away.>", completion = "<Hao looks up at you, struggling to pull himself from the rubble.>\n\nNo, no. I got it. HNNGHHH!!\n\nOkay, maybe I don't got it.", objectives = "Locate Hao Mann at the Greenstone Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29928] = { id = 29928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Have No Jade And I Must Scream", description = "Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites!\n\nNow even the plants are out to ruin me!\n\nYou need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.", progress = "<Mann looks at you expectantly, eyes wide and nostrils flared.>", completion = "Catch? They were playin' CATCH with my product?!\n\nI hope you showed those walkin' toothpicks a thing or two.\n\nYou know, maybe you ain't a cub after all. I've been lookin' for some muscle to help out with my problem at the quarry.\n\nAnd judgin' by the size of the Lorewalker's restoration project here, I think you'll need a lot more jade.", objectives = "Recover 15 Chunks of Jade from Puckish Sprites around the Greenstone Mason's Quarter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29929] = { id = 29929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapped!", description = "<Hao struggles against the rubble with all his might.>\n\nHNNNGHHH!!\n\nLet me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down.\n\nSome o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine.\n\nReally.", completion = "<Hao lets out a hearty laugh.>\n\nI seen 'em come runnin' out o' there like ol' Kher Shan himself were givin' chase.", objectives = "Free 8 Greenstone Miners in the Greenstone Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29930] = { id = 29930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Mined Is Yours", description = "Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time.\n\nI should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her.\n\nNow, I ain't never met no {race} t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.", progress = "Well? Where's Hao?\n\nDon't tell me you couldn't find him...", completion = "You did it! You brought my honey-bear back!\n\nOh thank you, {name}! Thank you!", objectives = "Board the jade cart and ride with Hao back to Emperor's Omen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29931] = { id = 29931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Serpent's Heart", description = "You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it.\n\nMy friend Foreman Raike is running the great statue project at the Serpent's Heart.\n\nBring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.", completion = "Am I seeing this right? A whole shipment of pure, high quality uncut jade?\n\nThank goodness. I knew Foreman Mann would come through for us.\n\nOh and you too. Thanks for bringing it by.", objectives = "Speak to Foreman Raike at the Serpent's Heart in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29932] = { id = 29932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Jade Serpent", description = "You've done us a huge favor here, traveler.\n\nNow that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent.\n\nWhen you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent.\n\nIf you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.", progress = "Yes?", completion = "You bring news from the Serpent's Spine?\n\n<The Elder Sage patiently listens to your tale of what occurred at the Jade Mines and at the large jade statue.>\n\nThank you for coming all this way, stranger. However, I cannot allow you to speak to the Jade Serpent right now.\n\nThe ancient one is very busy, and as you can see, is not here at the moment.", objectives = "Speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. Speak to Kitemaster Shoku for a kite ride to the temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29933] = { id = 29933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bees' Knees", description = "You really hozen friend, wikket? Let's see, hmm?\n\nHozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait!\n\nBo Bo sick from stings. Wikket get bait and take to Grookin.", progress = "Slicky food!", completion = "Woot! Woot! Wikket da Ook Dook!", objectives = "Collect 30 Bug Legs from Tigerflies in Tigers' Wood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29934] = { id = 29934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Ravenholdt", description = "If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure.\n\nThat's you, {name}.\n\nMostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!", progress = "So, are you ready to do some spying?", completion = "So far so good. Are you ready to do some spying?", objectives = "Speak to Mostrasz at the Vermillion Redoubt and fly to Ravenholdt Manor together.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29935] = { id = 29935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders are Orders", description = "Hmm, maybe wikket not so bad after all!\n\nOther baldskins not nice to hozen.\n\nHozen take this from bad wikkets!\n\nAll wikket loot goes to Kah Kah - Chief's orders!\n\nHere, wikket. You take it. Kah Kah will want to meet new hozen friend.\n\nHis camp south at Grookin Hill.", completion = "Hmm.\n\nMean wikkets fighting with nice wikkets?\n\nHozen fight mean wikkets too!", objectives = "Bring the Alliance Orders to Chief Kah Kah at Grookin.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29936] = { id = 29936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instant Messaging", description = "Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen.\n\nDook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah.\n\nHozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.", completion = "Impressive work, {name}.\n\nIt had not occurred to me that we might somehow befriend these creatures.\n\nWith their acceptance, we can now turn our attention to more important matters.", objectives = "Use the Hellscream's Fist Signal Flare near Chief Kah Kah at Grookin Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29937] = { id = 29937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furious Fowl", description = "So these guys like fish, huh? Well how about we finish what you started and make them LOVE us?\n\nI've still got some explosive powder from the wreck, just need something to attract the fish.\n\nGuts is sure to do the trick - never fails. I saw some birds flyin' around south of town.\n\nWell? Whatcha waitin' for?", progress = "You didn't touch that stuff with your hands did ya?", completion = "Yeah!\n\nNow that's the stuff. Just you wait and see...", objectives = "Collect 6 Fistfuls of Bird Guts from Bloodtalons in Dookin' Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29938] = { id = 29938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends and Foes", description = "These ookin' Jinyu grookin Kah Kah's nephews!\n\nWikket once kill many hozen. Now wikket kill many jinyu.", objectives = "Kill 7 Riverstride Jinyu at the Slicky Stream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29939] = { id = 29939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Bait", description = "There. I've plastered your bird guts over my explosives.\n\nI call 'em Gut Bombs, patent pending.\n\nSince you made friends with these fellas, how about you do the honors?\n\nJust light the fuse and throw 'em down by the shoreline!", progress = "I have yet to face a crisis that couldn't be fixed with dynamite.", completion = "We've just revolutionized how these cretins.. err, hozen, feed themselves.\n\nThey'll never be the same!", objectives = "Use the Gut Bombs at Murky Bank and collect 5 Exploded Slickies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29940] = { id = 29940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking a Crop", description = "Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops.\n\nThey took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them.\n\nIf my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?", progress = "If my father wants his vegetables, I'm going to need your help.", completion = "Perfect.\n\n<Ang surveys the bruised turnips and the soggy watermelons.>\n\nWhat were they DOING down there!?", objectives = "Obtain 5 Stolen Turnips and 5 Stolen Watermelons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29941] = { id = 29941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Horizon", description = "I recognize all you've managed to do here, {class}. My report to the Warchief will include an account of your deeds.\n\nBut there's no time to rest!\n\nThis land must be charted and prepared for Horde settlement. I've already selected an away team to do just that.\n\nFind them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide.\n\nYou'll be staying here with me. We have preparations to make.", progress = "Has the away team been dispatched, {name}?", completion = "Good work {name}.\n\nThe away team you assembled has departed.\n\nI hope Gorrok had the sense to change out of that ragged red shirt. I admire his patriotism, but he's had it on since we left Orgrimmar.\n\nThey won't be surprising anyone if he's wearing it...", objectives = "Speak to Shokia, Sergeant Gorrok, Shademaster Kiryn, and Chief Kah Kah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29942] = { id = 29942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silly Wikket, Slickies are for Hozen", description = "You think hozen crazy, wikket? Wait til you see hozen with no slickies!\n\nNot enough slickies for hozen and wikkets.\n\nSnappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers!\n\n<Eekle Eekle points to the south.>", progress = "Wikket grook all them ookin' snappers?", completion = "Now everybody got grub! Great hozen wisdom in Eekle Eekle.\n\nMaybe Eekle Eekle become Chieftain someday...", objectives = "Collect 4 Snapper Steaks from the Murky Bank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29943] = { id = 29943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guerrillas in our Midst", description = "Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, {name}.\n\nBut there's another side of this coin. We'd be naive to think the child was left alone.\n\nAny Alliance scum within sight of this land must be searching desperately for their precious princeling.\n\nYou and I are going to scour the area and root out his would-be rescuers.", completion = "Yes!\n\nBy Thrall's bloodied fist, I've missed hunting Alliance!", objectives = "Kill 8 Alliance Infiltrators near the Scenic Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29944] = { id = 29944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaders Among Breeders", description = "Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble.\n\nSure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.", progress = "The virmen here have strange habits. Stranger names.", completion = "<Chen nods.>\n\nGood work, {name}. You're not bad in combat.\n\nWhat do you say we team up for the next part?", objectives = "Slay Aiyu the Skillet, Jinanya the Clawblade, and Frenzyhop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29945] = { id = 29945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yellow and Red Make Orange", description = "Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen.\n\nHere's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots.\n\nThis can only end in comedy.\n\nI'll gather turnips. You find something that we can use to make edible orange paint.", progress = "You have the stuff ready for the paint? I went ahead and gathered some turnips.", completion = "Whoah, whoah, WHOAH! You brought back BLOOD? I guess I should have looked around for a half second before I asked you to bring me something red.\n\nYeesh!\n\n<Li Li turns back to the ingredients, spends a moment crushing the flower petals, and then mixes in some of the blood.>\n\n<She begins to giggle.>", objectives = "Obtain 10 Meadow Marigolds and 40 Vials of Animal Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29946] = { id = 29946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warren-Mother", description = "We've dealt with the alpha males. Now, the alpha female.\n\nVirmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood.\n\nYou know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?", completion = "That should take care of the virmen for a few weeks, at least. Enough time for Mudmug to get out a few good batches of beer, uninterrupted.\n\nAnd isn't that what's really important?", objectives = "Defeat Chufa, the Twitchheel Warren-Mother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29947] = { id = 29947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crouching Carrot, Hidden Turnip", description = "Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me.\n\nIt should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!", progress = "Go, torment those virmen, {name}!", completion = "Bah ha hah haaaa! I love messing with virmen.", objectives = "Toss Orange-Colored Turnips in front of 12 Twitchheel Hoarders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29948] = { id = 29948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieves to the Core", description = "You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either.\n\nWhile you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night.\n\nProbably usin' em for pillows, knowin' how they are.", progress = "I done told those virmen to stay off my land.", completion = "Aww, thank ya kindly, sir. You're a real gentleman.", objectives = "Recover 6 Stolen Sacks of Hops from the Twisted Warren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29949] = { id = 29949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy", description = "I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.", completion = "I know Uncle Chen's coming back. I'm not worried.\n\nActually, this is probably my big chance to finally explore Pandaria! No fat uncle tying me down!", objectives = "Have a drink with Chen, Li Li, and Mudmug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29950] = { id = 29950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li's Day Off", description = "Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest!\n\nYou want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.", progress = "You ready to go out yet?", completion = "That was great! You and I should go exploring again sometime.\n\nAnd it looks like we finished before Uncle Chen got back, too. Perfect.", objectives = "Bring Li Li to the Silken Fields, New Cifera, and Huangtze Falls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29951] = { id = 29951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muddy Water", description = "While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait.\n\nYou probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.", progress = "I knowed you for a friend as soon as I seen you.", completion = "You done good, {name}. You done good.", objectives = "Use Mudmug's Vial to gather muddy water.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29952] = { id = 29952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Dreams", description = "Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected.\n\n<Chen pours himself a mug of ale.>\n\nDo you want to hear the story?", progress = "...", completion = "Maybe I wasn't meant to settle down anyhow.", objectives = "Speak with Chen Stormstout and listen to his story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29966] = { id = 29966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Down the House", description = "Look, {name}!\n\nThese Alliance dogs built a camp up on the ridge.\n\nHere, take my grog. Let's make a fire they can see from Stormwind!\n\nFor the Horde!", completion = "The Alliance must be purged from this land, {name}!\n\nNo half-measures will do!", objectives = "Use Nazgrim's Grog to destroy the Alliance Camp atop the Scenic Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29967] = { id = 29967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boom Goes the Doonamite!", description = "It's an emergency!\n\nLooks like you stirred up a hornet's nest killin' all them fish-folk.\n\nThey're conductin' a full-on counterattack on Grookin Hill!\n\nI was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away!\n\nMeet me on the east side of the fort, and bring yer throwin' arm!", progress = "I think these methane-grenades are gunna impact the environment, if ya know what I mean...", completion = "I'd say repelling the attack is an understatement!", objectives = "Speak to Rivett east of Grookin Hill. Use his Methane Grenades to fend off the Jinyu attack.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29968] = { id = 29968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green-ish Energy", description = "One word: Methane!\n\nWe're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world.\n\nThat, and I ran out of blasting powder...\n\nSo, I need your help, {name}.\n\nNo, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself.\n\nYou gather up some wood for an outhouse - I'm thinking long-term here!", progress = "Gotta watch out for the wet ones...whewee!", completion = "Ah, the smell of progress, and methane.", objectives = "Gather 7 Green Branches in the Dookin' Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29969] = { id = 29969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Earthen Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.", objectives = "Repair the broken figurine using your skill and materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29970] = { id = 29970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Earthen Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.", objectives = "Repair the broken figurine using your skill and materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29971] = { id = 29971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scouts Return", description = "Hey, while you were out our scouts came back. And get this, they found some Alliance kid.\n\nYou should probably go debrief them.", completion = "We may have a problem.", objectives = "Speak with Shokia in Grookin Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29981] = { id = 29981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemming the Swarm", description = "I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong.\n\nThat wall over there was built to keep mantid off of pandaren lands.  Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there!\n\nThe only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.", progress = "If the flying mantid troops have always been able to fly over, why haven't they before now?", completion = "Lin asked you to help us out? Rather presumptive of her.\n\nStill, we are short-manned. We won't turn down your help... or the girl's. You have our thanks, {class}.", objectives = "Slay 14 Ik'thik mantid in Stoneplow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29982] = { id = 29982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation Orders", description = "A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes.\n\nMy Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.", progress = "Once these mantid are slain, we can get to work repairing the wall and restoring the town to its normal state.", completion = "A few stubborn ranchers want to make my job harder?\n\n<The Watch Commander sighs.>\n\nFine. I will rob no pandaren of his right to defend his land.", objectives = "Evacuate the Blacksoil Family, the Spadepaw Family, the Greentill Family, and the Marlfur Family.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29983] = { id = 29983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden Master", description = "We should be able to handle the defense of Stoneplow from here on out.\n\n<The Watch Commander motions towards Lin Tenderpaw.>\n\nLin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you.\n\nGo north.", completion = "You seek training?\n\n<The pandaren studies your physique for several seconds, without speaking.>\n\nAlright.", objectives = "Find Master Bruised Paw in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29984] = { id = 29984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Bamboo", description = "We will start with a test: The Trial of Bamboo.\n\nYour friend Lin failed this test.\n\nFollow me, and listen carefully to my instructions.", progress = "If you cannot pass this test, then there is probably no reason to continue our training.", completion = "You show promise, {name}. We will continue.\n\nIt is now time for your first round of training.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Bamboo Reeds 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29985] = { id = 29985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Be Mist", description = "The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back.\n\nConsider this part of your training.", progress = "Living outside of society has its advantages. I can focus all my energies on training, without being shackled to the societal conventions of modesty, politics, and basic personal hygiene. Here in the woods, I am free to be myself.", completion = "You follow directions well, {name}.", objectives = "Slay 12 Mist Incarnations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29986] = { id = 29986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fog Wards", description = "Trainee.\n\nSeveral wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep.\n\nYou will find one to the north, one to the west, and one to the south. Find these wards and light them.", progress = "See if you can light one of the wards while one of the mist incarnations is nearby.", completion = "You honor your people, {name}.", objectives = "Light the Northern Fog Ward, the Western Fog Ward, and the Southern Fog Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29987] = { id = 29987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Wood", description = "You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.", progress = "I'm prepared, {name}. Are you?", completion = "You have the gift of focus, {name}. Not many of my students make it this far.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Wooden Blocks 4 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29988] = { id = 29988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Eggs", description = "I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs.\n\nYes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.", progress = "How is your egg hunt going?", completion = "Now you know why I don't gather the eggs myself.\n\nShall we continue your training?", objectives = "Obtain 10 Emperor Tern Eggs, 4 Whitefisher Crane Eggs, and 1 Hornbill Strider Egg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29989] = { id = 29989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Fists: Trial of Stone", description = "You have accomplished much in the short time you have been here, {name}. I would not normally offer this test so soon... but I feel that you're ready.\n\nIt is time you attempted the Trial of Stone.", progress = "This test will be trying. You will test the strength of your fists against the strength of stone. Steel yourself, {name}.\n\nNot literally, of course.\n\nUnless you normally wear steel gloves... in which case, you may literally steel yourself.", completion = "<Master Bruised Paw bows before you.>\n\nStone quivers and breaks beneath your fists. You have the power to move mountains, if you so desire.\n\nThere is nothing more I can teach you.", objectives = "Speak with Master Bruised Paw, then successfully strike the Stack of Stone Blocks 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29990] = { id = 29990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training and Discipline", description = "I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, {name}. I'm not going to let it slip away.\n\nStill, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me.\n\nOh, and if you run into the others, maybe you should tell them where the Hidden Master is...", completion = "I'm glad to hear that Lin is well.\n\nOur defenses are holding, for now. The mantid continue to send their scouts over the wall, but they haven't gotten much farther than that.", objectives = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29992] = { id = 29992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenderpaw By Name, Tender Paw By Reputation", description = "I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first.\n\n<Lin whispers:> How'd you do that, by the way?\n\nIt looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in.\n\nIf you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.", progress = "Ow! Ow! Ow!", completion = "<Lin pauses for a moment to rub the leaves on her swollen paws.>\n\nThank you! I can prepare a proper ointment later, but this will do for now.", objectives = "Gather 18 Jademoon Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29993] = { id = 29993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Boy", description = "Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today.\n\nI'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave!\n\nNo son of mine is going to run off with a Goldendraft!\n\nI'm going to search around here for them.\n\nI do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?", completion = "You seek two lovers blind to the ambitions of their family names. They were here, seeking a way to hold to their path.\n\nSadly they did not find their answers among the trees or art.", objectives = "Speak with Inkmaster Wei.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29995] = { id = 29995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Dawn", description = "The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families.\n\nYou will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.", completion = "Oh stranger! Please tell me you can help us. They really hurt my Lo.", objectives = "Search the Shrine of the Dawn for Syra Goldendraft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29997] = { id = 29997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scryer's Dilemma", description = "Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple?\n\nWise Mari has been complaining recently of a disturbance in his temple.\n\nThe water elementals have gotten quite playful recently, and made off with his ceremonial staff.\n\nIf you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you.\n\nJust follow the path to the north.", progress = "The pools are clouded. I will need my staff to calm the spirits and speak to the water.", completion = "I am but an old jinyu, and those pesky water sprites were impossible to catch. Thank you, {name}, for returning my staff to me.", objectives = "Kill Water Fiends to recover Wise Mari's Staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29998] = { id = 29998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Librarian's Quandary", description = "Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work.\n\nWith thousands of ancient tomes to be transcribed, I can't afford to have him distracted.\n\nWould you follow the path south to the library and see what ails him?", completion = "The Elder Sage Rain-Zhu sent you?\n\nVery well. You shall help me.", objectives = "Speak to Lorewalker Stonestep in the temple library.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[29999] = { id = 29999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider's Bind", description = "Have you seen the young serpents in the training yard?\n\nThe littles ones tend to be mischievous, and some of them ran off to play before the training session.\n\nThe Mistress will get angry if she discovers they're missing.\n\nWould you go find them and bring them back to me? I don't want them to get into trouble.\n\nThey like to play out in the open, so look for them in courtyards and around the spires.", progress = "I hope they didn't give you too much trouble.", completion = "You found them and brought them all back!\n\nThey've really taken a liking to you.\n\nThank you so much!", objectives = "Find 4 Playful Serpents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30000] = { id = 30000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jade Serpent", description = "You came to deliver a message to the Jade Serpent, right?\n\n<The little girl tilts her head up at you inquisitively.>\n\nI guess it's time you met her.", completion = "Did you deliver your message?", objectives = "Listen to the Jade Serpent.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30001] = { id = 30001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moth-Ridden", description = "Moths have infested the library. Moths!\n\nAny librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms.\n\nAs it turns out, my assistants are a useless bunch of insect-fearing cowards.\n\nPlease, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!", progress = "I can see the moths eating the pages from here!", completion = "Yes, yes, thank you! You've thinned out their numbers wonderfully.", objectives = "Kill 8 Dappled Moths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30002] = { id = 30002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pages of History", description = "The worst possible thing has happened, {race}.\n\nWe. Have. Bookworms.\n\nThis is a critical situation. All Bookworms in the library must be eradicated at once to prevent their spread.\n\nWe must squash this problem, literally! Please examine the infested books in the library and squash any Bookworms that you find.", progress = "My stomach is too fragile to handle the squashing of bugs. Is it done?", completion = "Oh, wonderful! I am so relieved that we managed to avert disaster.\n\nNo no, don't get too close, please. You still have some squashed bug bits on your shoes.", objectives = "Search through the library books for infestations, then squash 12 Bookworms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30003] = { id = 30003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Book By Its Cover" }
quests[30004] = { id = 30004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything In Its Place", description = "You have helped us more than you can ever imagine, {name}.\n\nI do not know what I would do if our precious scrolls were ever to be lost.\n\nPlease return to the Elder Sage Rain-Zhu and tell him that the library is in order.", completion = "Lorewalker Stonestep is back to work?\n\nRemarkable. You were able to do what the last four priests I sent could not.\n\nI...I think my headache is disappearing.", objectives = "Speak to Elder Sage Rain-Zhu at the Temple of the Jade Serpent in Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30005] = { id = 30005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lighting Up the Sky", description = "Do you like fireworks, <sir/miss>?\n\nI love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty!\n\nI think there are still some old launchers lying around the temple.\n\nWould you go set off some big fireworks for me? It would make me so happy!", completion = "Yay! I saw the fireworks all the way from over here!\n\nThank you so much, {name}.", objectives = "Set off 8 fireworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30006] = { id = 30006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Around Us", description = "Despite our best efforts, the sha broke the seals around the main temple.\n\nIf we cannot hold them back here, their darkness will spread to the rest of the Jade Forest.\n\nWe need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.", completion = "Thank you, {name}. Every sha slain is another turn in the tide.", objectives = "Kill 15 sha invaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30007] = { id = 30007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Completed Arrival Phase" }
quests[30009] = { id = 30009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muster of Fort Grookin" }
quests[30011] = { id = 30011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Vision", description = "Please tell the Elder Sage Rain-Zhu that I will begin my work at once.", completion = "Wonderful! Knowing that the scryer has returned to his meditations has lifted a great burden from my shoulders.", objectives = "Speak to Elder Sage Rain-Zhu near the courtyard in the Temple of the Jade Serpent in the Jade Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30015] = { id = 30015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawn's Blossom", description = "Blood and Thunder! My axe hungers!\n\nWe won't return to Orgrimmar until every last Alliance is purged from this land.\n\nI will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement.\n\nIn the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script.\n\nDo what you must, but be quick about it.\n\nWar is brewing...", completion = "Greetings, {name}!\n\nWelcome to Dawn's Blossom, a home of my people.\n\nSadly I must depart. Alas, a Lorewalker's work is never done.\n\nMake yourself at home. Our people could surely make use of one with your talents.", objectives = "Speak with Lorewalker Cho in Dawn's Blossom.\n\nSpeak to the flightmaster in Grookin Hill for passage.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30019] = { id = 30019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Breach in the Wall" }
quests[30020] = { id = 30020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Out of Options" }
quests[30021] = { id = 30021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impenetrable" }
quests[30027] = { id = 30027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30028] = { id = 30028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grain Recovery", description = "Since you are heading south, can you try to recover some of the grain that these thieves made off with?\n\nWe saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.", progress = "Between birds and sprites we are never going to meet our quota to the Stormstout Brewery.", completion = "Why thank you very much stranger. This has not been a good day, but you certainly have helped us make it better.\n\nPlease, take this, you've earned it.", objectives = "Bring 8 Sacks of Grain to Grainlord Kai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30029] = { id = 30029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wee Little Shenanigans", description = "So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites.\n\nI HATE sprites. With their wee beady eyes and constant smiling.\n\nI would like to resolve this quietly. Can I buy your services to discreetly eliminate some of these grain thieves?", progress = "Oh good, they didn't turn you into a frog yet. I saw them do that once you know.", completion = "Thank you for your help stranger! Hopefully we can deal with the rest on our own from here.", objectives = "Kill 8 Tricky Maizers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30030] = { id = 30030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Sprite", description = "Just to be clear, what happened was an accident. What I did, I did for INDUSTRY!\n\nThere was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula.\n\nNow not only do they have a big sprite leading them, but he's one angry beast.\n\nIf I pay you, will you take him out?", progress = "Oh why? Why did I have to tamper with the natural order of things? All I wanted was to make these grains grow faster and more numerous.", completion = "Now that that's over I have some ideas on how to make a new concoction. We'll see.\n\nThank you for your help. Here is your reward.", objectives = "Defeat Cornan the Barley Barbarian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30031] = { id = 30031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taste Test", description = "As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life.\n\nYou should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.", progress = "None of this seems to taste sweet enough! What's the deal?", completion = "Huh. I guess none of that grain is going to work. Uncle Chen is pretty picky.\n\nMaybe the Grainlord knows where we can find something more... special.", objectives = "Taste the Aged Grain, Light Grain, Fresh Grain, and Malted Grain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30032] = { id = 30032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quest for Better Barley", description = "Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right.\n\nIf you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here.\n\nThere is even an old lift my father made when he would travel into the jungle.\n\nIn the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses.\n\nJust watch out for its guardians.", progress = "That jungle sounds spooky.", completion = "Now THIS smells like the right stuff!", objectives = "Find the Malted Cave Barley at the base of the Winds' Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30033] = { id = 30033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Spellblade and a Trainee's Hand Fan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30034] = { id = 30034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need a weapon suited to your talents. Retrieve a crossbow from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Crossbow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30035] = { id = 30035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a mace and a book of prayers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Mace and a Trainee's Book of Prayers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30036] = { id = 30036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve a pair of daggers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a pair of Trainee's Daggers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30037] = { id = 30037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Axe and a Trainee's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30038] = { id = 30038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lesson of the Iron Bough", description = "First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.", progress = "Picking up your first weapon is also a symbolic gesture. Every {class} that leaves these training grounds must be ready to take up arms in defense of their fellow {race}.", completion = "A fine weapon. It should suit your needs well.\n\nNow let's put it to use.", objectives = "Retrieve and equip a Trainee's Axe and a Trainee's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30039] = { id = 30039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Freshly arrived for your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength and cunning to be a {class}? Or are you destined to a life working in the fields?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30040] = { id = 30040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the intellect and force of will necessary to be a {class}? Or are you destined to a life scribing in the dusty libraries?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30041] = { id = 30041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the compassion and the keen eye of a {class}? Or are you destined to a life tending to the livestock?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30042] = { id = 30042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the awareness and wisdom necessary to be a {class}? Or are you destined to a life scribing in the libraries?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30043] = { id = 30043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the deftness and cunning necessary to be a {class}? Or are you destined to live the life of a humble merchant?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30044] = { id = 30044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength of will to be a {class}? Or are you destined to a life of tending to the shrines?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30045] = { id = 30045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Much to Learn", description = "Fresh to your training, your first task is simple: Speak to Master Shang Xi.", completion = "Today is the day when your fate will be decided. Do you have the strength and hardiness to be a {class}? Or are you destined to a life working the fields?\n\nEach has its place, but I can sense that you aspire to greatness.\n\nLet us begin our training, my newest pupil.", objectives = "Speak to Master Shang Xi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30046] = { id = 30046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Resolution", description = "You know what? I don't have to take this.\n\nI'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before.\n\nI'm Chen Stormstout, and I'm the best brewer alive.", completion = "Let's make some beer.", objectives = "Meet up with Chen Stormstout at Halfhill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30047] = { id = 30047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chen Taste Test", description = "Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that.\n\nLet's get this grain back to him at Halfhill.", completion = "Ah! Now these are some beautifully malted grains. The two of you have a good eye and nose.", objectives = "Return to Chen Stormstout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30048] = { id = 30048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li and the Grain", description = "I'll let you in on my brewing plan, {name}: I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol.\n\n<A frown appears on Chen's face.>\n\nI just realized... I never told my plans to Li Li. She'll have no idea what type of grain to bring back!\n\nCould you speak with her? I need her to bring back the sweetest malted grains she can find.", completion = "{name}? What are you doing here?\n\nSo, Uncle Chen wants sweet malts? No problem! Let's get to the taste testing.", objectives = "Speak with Li Li at the Imperial Granary in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30049] = { id = 30049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doesn't Hold Water", description = "Would you mind checking in on Mudmug? He may need some assistance bringing that water back.\n\nI'm sure he'll appreciate the help of a big, strong {class} like yourself to help him shoulder the load.", completion = "{name}! You here to help out? That's mighty swell of you.", objectives = "Speak with Mudmug at the Gilded Fan in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30050] = { id = 30050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gardener Fran and the Watering Can", description = "You want me to just GIVE you some hops? Pfshh! This is the third time today some little {race} like you has come up to me asking for food!\n\nYou want food? Then you'd better work!\n\n<She shoves a watering can into your hand.>\n\nNow go water my plants!", progress = "Water my plants you lazy {class}!", completion = "Hmmph!\n\nNice farming.", objectives = "Listen to Gardener Fran's orders and water 60 of her vegetables.\n\nYou can water plants while mounted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30051] = { id = 30051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Water Hunt", description = "Look at it, {name}: the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too.\n\nNo sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter?\n\nCome on, let's get movin'. We'll go scoop up some water together.", progress = "That Stormstout feller says that he's the best brewer that ever was. Might be true, couldn't tell ya one way or the 'nother as of yet.", completion = "Lookee that, neighbor! That is quite the collection of water we got here. With magical water like this, I'm sure that Chen'll make a brew that really shines.\n\nOr possibly a brew that lands someone in the outhouse for a month. I guess we'll just have to wait and see.", objectives = "Guide Mudmug to Swirling Pools within the Gilded Fan, and help him collect 30 pawfuls of Gladewater.\n\nIf you become separated from Mudmug, you can find him next to the giant banana in the Gilded Fan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30052] = { id = 30052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed War", description = "You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field.\n\nNow \"hop\" to it! Get it?", completion = "You weed like a champion.", objectives = "Pull 100 weeds from Gai Lan's field.\n\nYou can pull weeds while mounted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30053] = { id = 30053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hop Hunting", description = "With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops.\n\nI don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.", objectives = "Ask Gardener Fran, Gai Lan, and Den Mudclaw for hops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30054] = { id = 30054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough is Ookin' Enough", description = "Virmen, they bite too much.\n\nThey bite Mung-Mung's carrot. They bite Mung-Mung's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung's tail and foot.\n\nEnough is ookin' enough.\n\nYou fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.", progress = "You bring back those teeth, and maybe Mung-Mung will have some hops for you.", completion = "So many teeth! Maybe Mung-Mung will glue them together to make a tiny rake.", objectives = "Obtain 100 Virmen Teeth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30055] = { id = 30055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormstout's Hops", description = "All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.", completion = "Look at all these hops! This is quality stuff, too.\n\nWe're making headway, {name}. Soon we'll have all the ingredients to finally start brewing.", objectives = "Return to Chen Stormstout in Halfhill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30056] = { id = 30056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmer's Daughter", description = "Brave {class}, you could not have arrived at a better time. My daughter is missing!\n\nI've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning.\n\nCould you look for her?", completion = "No... no... get back... I don't want...\n\nWait, you're not a carrot. You're not a virmen either. You're here to save me?", objectives = "Find Mina Mudclaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30057] = { id = 30057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeing Orange", description = "Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me.\n\nLet's not waste any more time. Get me out of here!", completion = "What's all this fuss about carrots? I don't get it.", objectives = "Bring Mina Mudclaw back home to her father.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30058] = { id = 30058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mothallus!", description = "The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings.\n\nMothallus.\n\nYou have already faced its brood. Now we ask that you help us face the creature itself.\n\nPlease, {class}, venture into the pit and rifle the bait. This will bring the beast to you.\n\nOur mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.", progress = "Have you vanquished the beast?", completion = "We are pursuing perfection in our art and in ourselves. Along the way many mistakes will be made.\n\nI'm sure by tomorrow this field will be swimming with more mistakes. Still, we thank you for your help.", objectives = "Bait and defeat Mothallus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30059] = { id = 30059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moth Rebellion", description = "Oh... oh good! A {class}! Could you help me?\n\nI created a strain of vile monsters during my experiments to improve silk output.\n\nThe result was a full-scale moth rebellion. Can you use your {class}iness and destroy some of these mutants?", progress = "Master Goh keeps telling me I need to relax and that failure is part of learning. But this is a dangerous failure.\n\nThe kind that might get people killed.", completion = "It seems like there's not QUITE as many corrupted moths out there. At the very least, you've bought me some more time before I get in big, big trouble.", objectives = "Kill 6 Mutated Silkmoths and 8 Tiny Mutated Silkmoths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30063] = { id = 30063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Masks", description = "The sha may seem unstoppable, but this is not true.\n\nTheir masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm.\n\nBring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.", progress = "Please handle the masks carefully. If you are not careful, they will attempt to consume you.", completion = "I suspect these masks allow the sha to make a physical connection to our world.\n\nI must study them further if we are to banish these creatures forever.\n\nThank you, {name}. Your aid is greatly appreciated.", objectives = "Collect 8 Masks of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30064] = { id = 30064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Sutras", description = "My adepts had to abandon their studies when the sha invasion began.\n\nUnfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved!\n\nThe sutras can be found near the Training Pit and the Adept's Ring to the northeast.", progress = "How are the sutras? Are they damaged?", completion = "Thank you! What a relief it is to see these texts are safe.", objectives = "Collect 6 Ancient Sutras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30065] = { id = 30065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrows of Fortune", description = "Our war supplies grow low, but especially needed are additional arrows.\n\nOur serpent riders are skilled marksmen, but they can do little without ammunition.\n\nWe need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores.\n\nEvery arrow you retrieve will be used wisely.", progress = "Were you able to find any arrows?", completion = "These arrows are still in good shape. They will fly straight and true.\n\nGreat work, {name}.", objectives = "Collect 8 Defender's Arrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30066] = { id = 30066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Power", description = "Our temple defenders have battled relentlessly for hours. No doubt they grow tired.\n\nI will give you mantras to deliver to our fighters.\n\nDo not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.", progress = "Words hold great power. Use them wisely.", completion = "The sha's numbers are unending, and our numbers few. But we are not daunted by difficult odds.\n\nThank you for doing your part to protect our home, {race}.", objectives = "Deliver Ancient Mantras to 6 Yu'lon Guardians or Yu'lon Adepts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30067] = { id = 30067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of Doubt", description = "A terrible manifestation of the sha has appeared to the south.\n\nIt is trying to destroy an ancient relic, the Bell of a Thousand Whispers.\n\nThis bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power.\n\nPlease go and defeat this demon where it stands! We must save this relic!", progress = "The bell is said to contain the voices of a thousand fallen temple priests.", completion = "You have saved us. From what fate, I dare not imagine.", objectives = "Defeat the Shadow of Doubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30068] = { id = 30068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flames of the Void", description = "Do you see the violent black and white flames erupting all around the temple?\n\nThe greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple.\n\nWe have but one hope.\n\nTake flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.", progress = "These fires burn unlike anything in our world.", completion = "You have done much to help curb the fires. Thank you for your efforts.", objectives = "Fly your War Serpent near Pure Water Springs, then douse 6 Void Flames with the water carried in its mouth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30069] = { id = 30069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Plan Survives Contact with the Enemy", description = "Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least.\n\nRell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support.\n\nFight yer way through these dogs and find Rell!", progress = "This place is crawling with Horde soldiers - we can't advance on their leader with so many at our backs.", completion = "Great work! If you ever decide to give up your life of adventure, the SI:7 could use more talent like you...", objectives = "Kill 6 Garrosh'ar Grunts and 6 Garrosh'ar Gear-Greasers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30070] = { id = 30070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Ga'trul", description = "Alright <lad/lass>. We've taken enough jabs at this warlock army... now it's time to cut off the head.\n\nGa'trul's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.", progress = "What's the matter, {name}? Didn't you find Sully? Did Ga'trul elude you?", completion = "Sha...\n\nFighting the Horde on a foreign shore is hard enough.", objectives = "Slay Ga'trul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30072] = { id = 30072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Silk Comes From", description = "Would you like to be a Silkmaster for a day?\n\nThe first thing you'll need are fresh mulberry leaves. You can find them in our grove of mulberry bushes to the northwest.\n\nNext you will need to feed them to a hungry silkworm in our feeding pit to the west.\n\nAnd finally you should get some raw silk from our processing hut on the south side of our farm.\n\nHave fun!", progress = "Have you found all of the items? Did you pay close attention to our process?", completion = "Superb specimens. I will see to it they find their way to the right place. Please enjoy this free sample.", objectives = "Obtain Mulberry Leaves, feed 5 Hungry Silkworms, and get Raw Silk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30073] = { id = 30073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emperor", description = "We have everything we need. It's time to start brewing.\n\nPay attention, {name}... you might learn a thing or two.", progress = "It takes more than three seconds to make beer, {name}. Even when your name is Chen Stormstout.", completion = "Thanks for waiting so long. You are as patient as you are brave.", objectives = "Stand by and help Chen Stormstout with his brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30074] = { id = 30074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocking on the Door", description = "Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale?\n\nYou know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.", completion = "The door... it's boarded up?", objectives = "Meet up with Chen Stormstout at the entrance of the Stormstout Brewery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30075] = { id = 30075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Way", description = "Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!?\n\nThere is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.", progress = "This brewery - it's a disgrace to the Stormstout name! Something needs to be done!", completion = "I've had just about enough of this brewery. I'm starting to think that you and I should just bust down the wall and clean house.", objectives = "Slay 10 Ale-Addled Hozen or Mischievous Virmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30076] = { id = 30076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fanciest Water", description = "I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen.\n\nSo, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER.\n\nI reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?", progress = "This is gonna be great. It'll be just like makin' beer, but instead of water, I'm gonna use water sprite meat.", completion = "Looks like plain ol' water to me. It's hard to believe it's actually the corpse of a real, honest-to-goodness walkin'-around living thing.\n\nCan't wait to turn it into beer and drink it.", objectives = "Obtain 3 Spritewater Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30077] = { id = 30077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels, Man", description = "I can't believe that giant hozen! He's just throwing barrels everywhere!\n\nBarrels, man!\n\nIt looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use.\n\nWe're headed over to the brewery's rear entrance, to the east. Meet you there!", completion = "What is it with monkeys and barrels, anyway?", objectives = "Free 7 Barreled Pandaren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30078] = { id = 30078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "That's it, {name}. I've had enough of this.\n\nIf somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting.\n\nSo... we're going to break in through the back door. You, Li Li, Mudmug, and me.\n\nIt's gonna be a brawl in there.\n\nLet me know when you're ready.", progress = "Let's do this.", completion = "Take a look around - it's a lot calmer outside. All the brewery needed was somebody strong to take care of it.\n\nIt's going to take some time to clean this place up, but I don't really mind that so much.\n\nThis is, after all... my home.", objectives = "Defeat Eddy, Jooga, and the Fizzy Yellow Alemental.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30079] = { id = 30079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Eating Zhu's Watch?", description = "Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks!\n\nEveryone so busy sulking, they won't talk to Ken-Ken at all!\n\nCan you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?", progress = "Something definitely not right! Pandaren supposed to be HAPPY!", completion = "Only one lady-panda who's not crazy? This worse than Ken-Ken thought...", objectives = "Speak with the inhabitants in Zhu's Watch and find someone willing to talk to you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30080] = { id = 30080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Yi-Mo", description = "My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon.\n\nNow he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt.\n\nPlease, {class}, will you look for him?", progress = "<Yi-Mo lets out a long sigh.>", completion = "Let me guess: my aunt sent you?", objectives = "Look for Yi-Mo Longbrow somewhere northeast of Zhu's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30081] = { id = 30081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materia Medica", description = "Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick.\n\nNeed to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds.\n\nThat just leave salt... Mei might know where we can find some.", progress = "Can't believe Ken-Ken did not think of this sooner. It's the ONE thing that can ruin his day...", completion = "Pandaren got a case of the spooky-dooks!\n\nDooks get scared sometimes, don't wanna come out. Poor, fluffy mopey-dopes must be ready to explode by now!\n\nThis just the thing to bring 'em out. That make pandaren happy for sure!\n\nJust like ol' gramma used to say: can't THROW if can't GO!", objectives = "Gather 4 Chunks of Honeycomb, 4 Slick Mudfish, and 4 Salty Cores from Zhu Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30082] = { id = 30082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheer Up, Yi-Mo", description = "Ever since this storm began, I've just been... tired.\n\nNot physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know?\n\nHow can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me.\n\n<Yi-Mo sighs deeply and continues staring off into the sky. It doesn't look like he's going anywhere.>", completion = "I can't believe he was actually going to do that... This despair is worse than I had even imagined.\n\nI cannot thank you enough for bringing him back.", objectives = "Bring Yi-Mo Longbrow back to Zhu's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30083] = { id = 30083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Province", description = "With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town.\n\nMost of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want!\n\nI want to send a message that Zhu's Watch is not to be crossed.\n\nWill you be my messenger?", completion = "Thank you, {name}. That should teach those savages to know their boundaries.", objectives = "Kill 10 Wildscale Saurok or Wildscale Herbalists in Zhu Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30084] = { id = 30084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borderlands", description = "Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times.\n\nNobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries.\n\nPlease, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.", completion = "Thank you, {name}.\n\nZhu Province serves as a corridor from the upper tier of the valley down to the sea.\n\nKeeping the province safe requires daily efforts to maintain a border against the savage Krasarang Wilds.", objectives = "Light the Memorial Flame of Zhu, Memorial Flame of Rin, and Memorial Flame of Po along the southwest border of Zhu Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30085] = { id = 30085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Brewery", description = "We need to find out what's going on inside that brewery, {name}!\n\nWe may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!", completion = "You came! Great!\n\nI'm looking forward to fighting by your side again, {name}.", objectives = "Speak to Chen Stormstout inside the Stormstout Brewery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30086] = { id = 30086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for the Hidden Master", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs.\n\nI'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.", completion = "Were you listening in? Don't worry, I don't mind. You're welcome to search for the hidden master as well.\n\nThough, if you do find him, I'd appreciate if you came back here and told me where he was.", objectives = "Listen to Xiao and his companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30087] = { id = 30087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Kung Fu Intro", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", objectives = "Listen to Xiao and his companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30088] = { id = 30088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why So Serious?", description = "Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad...\n\nWe try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties.\n\nKen-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have!\n\nOh, and some paint! Mei might know where to find.", progress = "<Ken-Ken is hard at work carving something out of tree bark.>\n\nThis gonna be great, you'll see.", completion = "Just in time! All done... look!\n\n<Ken-Ken holds up a carved wooden mask with a ridiculous face.>\n\nNow we put on finishing touches and we gots a guaranteed FUN MACHINE!", objectives = "Collect 18 Huge Panther Fangs and 1 Jar of Pigment from Zhu Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30089] = { id = 30089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply Directly to the Forehead", description = "Well... THAT was unexpected!\n\nCome to think of it, now Ken-Ken remember why hozen use mask in the first place...\n\nA legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground.\n\nWe should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT.\n\nLet's do this, {name}!", progress = "This must be the emperor's sad coming back! That is some oooold sad.\n\nKen-Ken bet pandaren sad get stronger with age, too, like pandaren booze.", completion = "We saving pandaren, but the land still sad... Look, rain's not stopping at all!\n\n<Ken-Ken shakes his tiny fists at the sky.>\n\nHow many more butts we gotta punch before we fix this town?!\n\n<The sky darkens in response.>", objectives = "Use Ken-Ken's Mask to cure 8 Despondent Wardens of Zhu in Zhu's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30090] = { id = 30090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhu's Despair", description = "Hmm... Is that Yi-Mo kid over there?\n\n<Ken-Ken squints against the increasing torrents of rain.>\n\nIt is! He's at the well, and he's not lookin' so good.\n\nKen-Ken got a bad feeling about this...", completion = "We did some good work here today, {name}.\n\nMonastery always tell us to leave a place better than we find it.", objectives = "Exorcise the Sha of Despair energy from Yi-Mo Longbrow in Zhu's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30091] = { id = 30091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Pandaria", description = "All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky.\n\nDespite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched.\n\nNow the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.", progress = "I don't know why this is happening, but I can say for certain that those elementals were the start of it all.", completion = "Thank you, {class}.\n\nIt's time we take back our land from this curse.", objectives = "Kill 12 Weeping Horrors in Zhu Province.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30092] = { id = 30092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Man in Gilneas", description = "If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas.\n\nWe haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers, a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital.\n\nFind him and he'll direct you to the target.", completion = "Ravenholdt sent you? I hope you're a better assassin than the others.", objectives = "Seek out Zazzo Twinklefingers near the ruins of Gilneas City in Gilneas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30093] = { id = 30093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassinate Creed", description = "The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out.\n\nOnly a surgical assassination can end this!\n\nThe bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district.\n\nI'll keep an eye on you and pull you out if there's any trouble.\n\n...There WILL be trouble!", progress = "Hiram Creed. Among the black dragons, he is known as \"Creetharus.\"", completion = "Creed is finished. The Gilneans who followed his lead are on their own now - assuming his corrupted draconic blood works its way out of their system without killing them.\n\nEither way they're no longer a concern of ours.", objectives = "Stealth into the ruins of Gilneas City and slay Hiram Creed within the military district.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30094] = { id = 30094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", completion = "{name}, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid.", objectives = "Speak with Nozdormu at the End Time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30095] = { id = 30095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End Time", description = "Nozdormu, the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details.\n\nIt is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself.\n\nHe awaits you at the End Time, in the distant future. I can help you to travel there, if you so choose.", completion = "{name}, you have arrived. This is good. I apologize for bringing you to this strange place, and under such suspicious circumstances.\n\nI have a good reason for doing so.\n\nWe are going to kill Deathwing. And I require your aid.", objectives = "Speak with Nozdormu at the End Time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30096] = { id = 30096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murozond", description = "If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me.\n\nThe creature that blocks us from accessing this time passage is named Murozond. He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing.\n\nThis is why you were brought here, {name}.", progress = "This is a future of Azeroth, yes... but not an inevitable one.\n\nThis future is what my fellow aspects are trying to avoid.", completion = "Murozond is no more. The timeways are open to me once again.", objectives = "Slay Murozond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30097] = { id = 30097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archival Purposes", description = "From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us.\n\nWe believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines.\n\nTake this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.", progress = "Nozdormu is acting with haste. This is something that Nozdormu does not usually do.\n\nNormally I would be more thorough with my archival. However, given the circumstances, we are forced to pick and choose what we record... and to employ the help of mercenaries like you.", completion = "<Alurmi collects the vessel from you.>\n\nI will handle these from here. Of course, they must be properly labeled, documented, and stored.", objectives = "Slay two of the Echoes within the End Time, then allow Alurmi's Vessel to archive their information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30098] = { id = 30098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Well of Eternity", description = "We must move quickly, before any remaining Infinite agents intervene. Time is precious.\n\nI will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.", completion = "Let us proceed.", objectives = "Speak with Nozdormu at the Well of Eternity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30099] = { id = 30099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Unending Numbers", description = "Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed.\n\nIf my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting.\n\nHelp Illidan disable the demons' portals, then slay their leader, Peroth'arn.", progress = "You should temporarily lay aside any prejudices you may carry against Illidan. Remember, you are ten thousand years in your past, and he must not be punished for any future crimes.", completion = "Good. We march on.", objectives = "Disable the three demon portals, then slay Peroth'arn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
